"""在 PATH 上把命令名解析成磁盘路径。

Windows 上「命令名」通常不带扩展名，例如 ``where``、``git``、``build``。
Shell 之所以能找到它们，是因为按 :envvar:`PATHEXT` 里声明的扩展名顺序
逐个试探。任何要自己启动外部程序的工具都必须照做，否则只能看见 ``.exe``。
"""

import os

from .errors import CommandNotFound

#: 找不到 PATHEXT 时使用的兜底扩展名。
EXECUTABLE_EXTENSIONS = (".exe",)


def search_dirs():
    """返回 PATH 中需要搜索的目录列表。"""
    raw = os.environ.get("PATH", "")
    return [d for d in raw.split(os.pathsep) if d]


def executable_extensions():
    """返回按优先级排列的可执行扩展名。

    优先使用环境变量 :envvar:`PATHEXT`；它缺失或为空时才退回内置兜底值。
    返回的每个扩展名都带前导点（例如 ``.COM``、``.EXE``、``.CMD``），
    顺序与 PATHEXT 中声明的一致。
    """
    raw = os.environ.get("PATHEXT", "")
    exts = []
    for part in raw.split(os.pathsep):
        part = part.strip()
        if not part:
            continue
        if not part.startswith("."):
            part = "." + part
        exts.append(part)
    if not exts:
        return EXECUTABLE_EXTENSIONS
    return tuple(exts)


def _has_extension(name):
    """判断命令名本身是否已经带了扩展名。"""
    return bool(os.path.splitext(name)[1])


def _candidate_names(name):
    """按优先级生成 ``name`` 对应的候选文件名。

    名字已带扩展名时直接使用原名（不再叠加扩展名）；否则按
    :func:`executable_extensions` 的顺序逐个拼接。
    """
    if _has_extension(name):
        return [name]
    return [name + ext for ext in executable_extensions()]


def _find_in_directory(directory, name):
    """在单个目录内按 PATHEXT 顺序查找 ``name``，命中则返回完整路径。"""
    for candidate in _candidate_names(name):
        path = os.path.join(directory, candidate)
        if os.path.isfile(path):
            return path
    return None


def resolve(name):
    """把 ``name`` 解析成磁盘上的绝对路径。

    解析遵循 :envvar:`PATH` 的目录顺序与 :envvar:`PATHEXT` 的扩展名
    顺序；``name`` 本身带扩展名时不再叠加。找不到时抛
    :class:`CommandNotFound`。
    """
    if not name:
        raise CommandNotFound(name)

    for directory in search_dirs():
        found = _find_in_directory(directory, name)
        if found is not None:
            return os.path.abspath(found)

    raise CommandNotFound(name)

